BEGIN;
CREATE TABLE "Clientes" (
    "IdCliente" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" VARCHAR(100) NOT NULL,
    "Dni" VARCHAR(8) NOT NULL,
    "Telefono" VARCHAR(15) NOT NULL,
    "Email" VARCHAR(100) NOT NULL,
    CONSTRAINT "UQ_Clientes_Dni" UNIQUE ("Dni"),
    CONSTRAINT "UQ_Clientes_Email" UNIQUE ("Email")
);
CREATE UNIQUE INDEX "UX_Clientes_Email_Normalizado" ON "Clientes" (lower("Email"));
CREATE TABLE "Vehiculos" (
    "IdVehiculo" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Placa" VARCHAR(7) NOT NULL,
    "Marca" VARCHAR(30) NOT NULL,
    "Modelo" VARCHAR(50) NOT NULL,
    "Anio" INTEGER NOT NULL,
    "Kilometraje" INTEGER NOT NULL,
    "IdCliente" INTEGER NOT NULL,
    CONSTRAINT "UQ_Vehiculos_Placa" UNIQUE ("Placa"),
    CONSTRAINT "CK_Vehiculos_Placa" CHECK ("Placa" ~ '^[A-Z0-9]{3}-[A-Z0-9]{3}$'),
    CONSTRAINT "CK_Vehiculos_Anio" CHECK ("Anio" BETWEEN 1900 AND 2100),
    CONSTRAINT "CK_Vehiculos_Kilometraje" CHECK ("Kilometraje" BETWEEN 0 AND 9999999),
    CONSTRAINT "FK_Vehiculos_Clientes" FOREIGN KEY ("IdCliente")
        REFERENCES "Clientes" ("IdCliente") ON DELETE RESTRICT
);
CREATE INDEX "IX_Vehiculos_IdCliente" ON "Vehiculos" ("IdCliente");
INSERT INTO "Clientes" ("Nombre", "Dni", "Telefono", "Email") VALUES
